alter table streaming_entitlements add constraint streaming_entitlements_dates_chk check(ends_at is null or ends_at>starts_at);alter table streaming_watch_history add constraint streaming_watch_progress_reasonable_chk check(progress_seconds<=86400);alter table streaming_events add constraint streaming_event_position_reasonable_chk check(position_seconds is null or position_seconds<=86400);create index if not exists idx_streaming_entitlements_org_scope on streaming_entitlements(organization_id,subscriber_id,scope_type,active);create index if not exists idx_streaming_favorites_org_subscriber on streaming_favorites(organization_id,subscriber_id);create index if not exists idx_streaming_history_org_subscriber on streaming_watch_history(organization_id,subscriber_id,last_watched_at desc);